import{_ as e,o as d,c as r,ag as o}from"./chunks/framework.DNmTgtHf.js";const p=JSON.parse('{"title":"Part 22 — DevOps & Infrastructure","description":"","frontmatter":{},"headers":[],"relativePath":"todo/study_plan/parts/Part_22_DevOps.md","filePath":"todo/study_plan/parts/Part_22_DevOps.md"}'),s={name:"todo/study_plan/parts/Part_22_DevOps.md"};function a(i,t,n,l,c,u){return d(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="part-22-—-devops-infrastructure" tabindex="-1">Part 22 — DevOps &amp; Infrastructure <a class="header-anchor" href="#part-22-—-devops-infrastructure" aria-label="Permalink to &quot;Part 22 — DevOps &amp; Infrastructure&quot;">​</a></h1><blockquote><p><strong>Sprint allocation:</strong> Week 10 (shared with start of Part 29). <strong>Budget: ~5-6 hrs.</strong></p></blockquote><h2 id="_22-devops-infrastructure-—-topic-inventory" tabindex="-1">22 DevOps &amp; Infrastructure — topic inventory <a class="header-anchor" href="#_22-devops-infrastructure-—-topic-inventory" aria-label="Permalink to &quot;22 DevOps &amp; Infrastructure — topic inventory&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>Topic</th><th>Tags</th><th>Tier</th><th>Time</th><th>Done</th><th>Partial</th><th>Grilling</th><th>Visit Again</th><th>Notes</th><th>Resources</th></tr></thead><tbody><tr><td>1</td><td>AWS IAM — roles, policies, trust relationships, instance profiles</td><td>🔴 💼 🔐</td><td>MP</td><td>2 hrs 20 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>(Cross-ref Part 13 IAM)</td><td>💻 Warm-up: write IAM role with EC2 trust policy + attach a least-privilege S3 read policy + verify via aws sts get-caller-identity from the instance (20 min)</td></tr><tr><td>2</td><td>AWS VPC, subnets (public/private), security groups, NACLs basics</td><td>🔴 💼 🔐</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>(Cross-ref Part 13 VPC)</td><td></td></tr><tr><td>3</td><td>Docker — image layers, multi-stage builds, .dockerignore, distroless</td><td>🔴 💼</td><td>MP</td><td>2 hrs 15 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td>💻 Warm-up: write a multi-stage Dockerfile for a Spring Boot app — JDK stage + JRE runtime + .dockerignore (15 min)</td></tr><tr><td>4</td><td>Docker — networking, volumes, compose</td><td>🔴 💼</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>5</td><td>Terraform — providers, state, modules, workspaces</td><td>🔴 💼</td><td>D</td><td>2 hrs 30 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td>💻 Warm-up: write Terraform that provisions an S3 bucket with versioning + lifecycle, apply + destroy (30 min)</td></tr><tr><td>6</td><td>Daily Linux fluency — ps, top, htop, lsof, netstat / ss, tcpdump, strace</td><td>🔴 💼</td><td>D</td><td>3 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td>💻 Warm-up: identify which process holds port 8080 (<code>lsof -i :8080</code>), find which files a process has open (<code>lsof -p &lt;pid&gt;</code>), watch syscalls (<code>strace -p &lt;pid&gt;</code>) (30 min)</td></tr><tr><td>7</td><td>systemd basics</td><td>🔴 💼</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>8</td><td>Filesystem layout, permissions, ulimits</td><td>🔴 💼</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>9</td><td>Kubernetes — Pod, Deployment, Service (ClusterIP / NodePort / LoadBalancer), Ingress (resource vs controller), <code>ingressClassName</code> (multiple controllers per cluster, e.g., <code>nginx</code> vs <code>nginx-internal</code>), nginx annotations (<code>proxy-body-size</code>, CORS, <code>rewrite-target</code>, <code>server-snippet</code>), ConfigMap, Secret; public LB vs internal LB (&quot;two doors into the same building&quot; model), AWS LB controller annotations (<code>service.beta.kubernetes.io/aws-load-balancer-internal</code>)</td><td>🔴 💼</td><td>D</td><td>4 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td>💻 Warm-up: deploy a Spring Boot pod via Deployment + expose via Service + ClusterIP, kubectl get pods (30 min)</td></tr><tr><td>10</td><td>Container security — image scanning (Trivy, Snyk, ECR scanning), distroless, SBOM (Syft, Grype), supply-chain (Sigstore/cosign)</td><td>🟠 💼 🔐</td><td>MP</td><td>2 hrs 30 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td>💻 Warm-up: scan your Spring Boot Dockerfile with Trivy or grype, identify top 5 CVEs, generate an SBOM with syft (30 min)</td></tr><tr><td>11</td><td>Kubernetes RBAC + ServiceAccount + Pod Security Standards (restricted/baseline/privileged)</td><td>🟠 💼 🔐</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>12</td><td>Kubernetes — probes (liveness, readiness, startup), resource requests / limits</td><td>🟠 💼</td><td>MP</td><td>2 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>13</td><td>Kubernetes — HPA, VPA, cluster autoscaler</td><td>🟠 💼</td><td>MP</td><td>2 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>14</td><td>Kubernetes — StatefulSet, DaemonSet, Job, CronJob</td><td>🟠 💼</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>15</td><td>Helm, Kustomize</td><td>🟠 💼</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>16</td><td>Pulumi, CDK alternatives</td><td>🟠 💼</td><td>M</td><td>1 hr</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>17</td><td>GitHub Actions / GitLab CI / Jenkins — pipelines, secrets</td><td>🟠 💼</td><td>MP</td><td>2 hrs 15 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td>💻 Warm-up: GitHub Actions workflow that runs mvn test on PR + deploys on push to main (15 min)</td></tr><tr><td>18</td><td>ArgoCD, Flux — GitOps model, sync loop (effectively <code>kubectl apply</code> driven by git state), how <code>kustomization.yaml</code> decides which manifests get applied, drift detection</td><td>🟠 💼</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>19</td><td>Blue-green, canary, feature flags</td><td>🟠 💼</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>20</td><td>Bash scripting fluency</td><td>🟠 💼</td><td>MP</td><td>2 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>21</td><td>awk, sed, jq for log mining</td><td>🟠 💼</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>22</td><td>Service mesh — Istio, Linkerd</td><td>🟡</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>23</td><td>LaunchDarkly, Unleash, custom flag systems</td><td>🟡</td><td>M</td><td>1 hr</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>24</td><td>Performance — iostat, vmstat, sar</td><td>🟡</td><td>M</td><td>1 hr</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>25</td><td>SSH — key-based auth, <code>~/.ssh/config</code>, ssh-agent, host key verification, port forwarding (<code>-L</code>/<code>-R</code>/<code>-D</code>), ProxyJump / bastion</td><td>🟠 💼 🔐</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td>💻 Warm-up: generate ed25519 keypair, add to authorized_keys on a remote, set up a <code>~/.ssh/config</code> alias with ProxyJump bastion, verify host key is pinned in known_hosts (20 min)</td></tr></tbody></table><h2 id="time-summary" tabindex="-1">Time summary <a class="header-anchor" href="#time-summary" aria-label="Permalink to &quot;Time summary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Scope</th><th>Hours (zero baseline)</th><th>Weeks @ 10–12 hrs/wk</th><th>Actual time</th></tr></thead><tbody><tr><td>🔴 MUST only (Sprint priority — 3-month plan)</td><td>~20.08 hrs</td><td>~1.83 wk</td><td></td></tr><tr><td>🔴 + 🟠 HIGH (must + high — senior coverage)</td><td>~42.33 hrs</td><td>~3.85 wk</td><td></td></tr><tr><td>Full Part (all items including 🟡)</td><td>~45.83 hrs</td><td>~4.17 wk</td><td></td></tr></tbody></table><h2 id="frequently-asked" tabindex="-1">Frequently asked <a class="header-anchor" href="#frequently-asked" aria-label="Permalink to &quot;Frequently asked&quot;">​</a></h2><ol><li><strong>Q:</strong> Multi-stage Docker build — why? <ul><li><strong>Why asked:</strong> Senior Docker fluency. Smaller image: build stage has JDK + Maven + sources (huge), runtime stage has only JRE + jar (~150 MB). Better security: no build tools in production image. Faster cold starts. Distroless even smaller (no shell, no package manager).</li></ul></li><li><strong>Q:</strong> K8s readiness vs liveness probe — when does each kick in? <ul><li><strong>Why asked:</strong> Operational canonical. Liveness: &quot;is the container healthy enough to keep running?&quot; If fails, K8s restarts it. Readiness: &quot;is the container ready to serve traffic?&quot; If fails, K8s removes it from Service endpoints (no restart). Common bug: same endpoint for both → restart loop during heavy GC.</li></ul></li><li><strong>Q:</strong> Terraform state — where does it live, and what&#39;s the trap? <ul><li><strong>Why asked:</strong> Operational depth. State stores resource IDs + metadata. Local file by default — DANGER for teams (race conditions, lost state). Right answer: remote backend (S3 + DynamoDB lock, or Terraform Cloud) so multiple engineers can collaborate safely. State contains secrets — encrypt at rest.</li></ul></li><li><strong>Q:</strong> Blue-green vs canary — when does each fit? <ul><li><strong>Why asked:</strong> Modern deployment. Blue-green: two identical environments, atomic traffic switch. Good for stateless services, instant rollback. Cost: double the capacity. Canary: gradual traffic shift (1% → 10% → 50% → 100%), with metrics gating. Good for risk reduction on user-impactful changes. Better with feature flags layered on.</li></ul></li><li><strong>Q:</strong> Walk through K8s Pod-to-Pod networking. <ul><li><strong>Why asked:</strong> K8s internals. Each Pod gets a cluster-unique IP. Service abstracts a stable VIP over a set of Pods (selector → endpoint slice). kube-proxy (or eBPF / Cilium) handles VIP → backend Pod routing on each node. DNS resolution via CoreDNS: <code>service.namespace.svc.cluster.local</code>.</li></ul></li><li><strong>Q:</strong> Your CI build flakiness rate is 5%. How do you triage and fix? <ul><li><strong>Why asked:</strong> Senior engineering practice. (1) Categorize failures: infra-flaky (retry the build), test-flaky (mark + investigate), real bug. (2) Quarantine tests with high flake rate. (3) Address root causes in priority order. (4) Set a flake budget — fail the build if breached. CI flakiness is a tax on the whole team.</li></ul></li><li><strong>Q:</strong> <code>ps aux</code> shows your Java service has 12 threads named &quot;ForkJoinPool.commonPool-worker-*&quot;. What&#39;s likely happening? <ul><li><strong>Why asked:</strong> Linux + Java intersection. Parallel streams (or other ForkJoin uses) spin up worker threads on the common pool. 12 threads = your machine has ~12 cores. Potential issue: parallel streams on web server threads can starve the common pool. Recommend dedicated executors for app-level parallel work.</li></ul></li><li><strong>Q:</strong> Container image scanning — Trivy vs Snyk vs ECR scanning, which when? <ul><li><strong>Why asked:</strong> Supply-chain security fluency expected of seniors. <strong>Trivy:</strong> free, OSS, broad feature set (CVE scan + IaC + secrets + SBOM), actively maintained by Aqua, slower on large images but the default for OSS pipelines. <strong>Snyk:</strong> commercial, polished UX, deep CI/CD integrations, dev-friendly remediation advice, license cost scales with repos. <strong>ECR scanning:</strong> free baseline (basic) or enhanced (Inspector-backed) on AWS, runs at-rest on pushed images, basic CVE scan only — no SBOM, no IaC, no secrets detection. <strong>Recommendation:</strong> Trivy as the gate in CI pipelines (fail builds on critical CVEs) + ECR enhanced scanning at rest (catches CVEs that surface <em>after</em> the image is pushed, since vuln DBs update continuously). Add Snyk if the org already pays for it or wants polished triage dashboards.</li></ul></li></ol><h2 id="trick-questions-gotchas" tabindex="-1">Trick questions / gotchas <a class="header-anchor" href="#trick-questions-gotchas" aria-label="Permalink to &quot;Trick questions / gotchas&quot;">​</a></h2><ol><li><strong>Q:</strong> Your Dockerfile has <code>RUN apt-get install</code> followed by <code>RUN apt-get install</code> on different lines. Why does this bloat the image? <ul><li><strong>Gotcha:</strong> Each RUN creates a new layer. Even if you <code>apt-get autoremove</code> later, the deleted files remain in earlier layers. Right: combine into one RUN with <code>&amp;&amp;</code> chain, or use multi-stage build. Also: use <code>apt-get install --no-install-recommends</code> to avoid optional packages.</li></ul></li><li><strong>Q:</strong> Your K8s pod gets killed periodically. Logs show &quot;OOMKilled&quot; but <code>top</code> inside the container showed plenty of free memory. What&#39;s happening? <ul><li><strong>Gotcha:</strong> Container memory limits != host memory. K8s kills based on cgroup limits. JVM by default doesn&#39;t respect cgroup limits (pre-Java 8u131) — uses host RAM as max heap. Fix: <code>-XX:+UseContainerSupport</code> (default in modern JVMs) + <code>-XX:MaxRAMPercentage=75.0</code> to leave headroom for native memory.</li></ul></li><li><strong>Q:</strong> Terraform apply succeeds but the resource doesn&#39;t appear in AWS console. What&#39;s wrong? <ul><li><strong>Gotcha:</strong> Provider region mismatch. Default region in Terraform vs the region you&#39;re viewing in console. Always: <code>aws_region</code> explicitly set in provider config; AWS console region matches.</li></ul></li><li><strong>Q:</strong> GitHub Actions secret <code>&amp;#123;&amp;#123; secrets.AWS_KEY &amp;#125;&amp;#125;</code> is logged in the action output. Why? <ul><li><strong>Gotcha:</strong> Likely echoed via <code>echo</code> or printed via debug. GitHub auto-redacts secrets in logs, but commands that output the secret via base64 / encoded form bypass the redaction. Never echo secrets. Use OIDC federation for cloud access — no static secrets needed.</li></ul></li></ol><h2 id="mastery-candidates-top-3–5-from-this-part-—-suggestions-not-commitments" tabindex="-1">Mastery candidates (top 3–5 from this Part — suggestions, not commitments) <a class="header-anchor" href="#mastery-candidates-top-3–5-from-this-part-—-suggestions-not-commitments" aria-label="Permalink to &quot;Mastery candidates (top 3–5 from this Part — suggestions, not commitments)&quot;">​</a></h2><ul><li><strong>Docker multi-stage + distroless image</strong> (~2.5 hrs row 1) — production-grade Dockerfile. Build slim image, document size reduction, demonstrate cold-start improvement.</li><li><strong>Terraform state + collaboration</strong> (~2.5 hrs row 3) — remote backend with locking. Module structure. Workspaces for env separation. Migration story from local to remote.</li><li><strong>K8s deployment patterns</strong> (~3 hrs rows 7+8+9) — Pod / Deployment / Service / Ingress + probes + autoscaling. Deploy a real-ish workload, observe HPA scaling.</li><li><strong>Linux production debugging fluency</strong> (~3 hrs row 4) — lsof, strace, tcpdump, ss, jstack, jmap on a real Java service. Daily senior signal.</li></ul><h2 id="hands-on-exercises-practice-advanced" tabindex="-1">Hands-on exercises (Practice + Advanced) <a class="header-anchor" href="#hands-on-exercises-practice-advanced" aria-label="Permalink to &quot;Hands-on exercises (Practice + Advanced)&quot;">​</a></h2><p>Warm-up DevOps exercises are listed inline in the topic-table Resources column (counted in main Time summary). Longer exercises below are tracked separately.</p><h3 id="practice-—-mid-level-30-60-min-each" tabindex="-1">Practice — mid-level (~30-60 min each) <a class="header-anchor" href="#practice-—-mid-level-30-60-min-each" aria-label="Permalink to &quot;Practice — mid-level (~30-60 min each)&quot;">​</a></h3><ol><li><strong>Distroless Spring Boot Docker image</strong> (~60 min) — multi-stage Dockerfile: build stage uses <code>eclipse-temurin:17-jdk</code>, runtime uses <code>gcr.io/distroless/java17-debian12</code>. Compare image size to fat-jar approach.</li><li><strong>Terraform module for VPC</strong> (~60 min) — write a reusable module that takes CIDR + AZs as input, outputs VPC + public/private subnets + route tables. Apply, destroy, reapply.</li><li><strong>K8s rolling deployment + readiness probe</strong> (~45 min) — Deployment manifest with readiness probe on <code>/actuator/health/readiness</code>. Trigger a rolling update with broken probe — observe no traffic shift. Fix probe, re-deploy.</li></ol><h3 id="advanced-—-senior-grade-depth-60-min-each" tabindex="-1">Advanced — senior-grade depth (~60+ min each) <a class="header-anchor" href="#advanced-—-senior-grade-depth-60-min-each" aria-label="Permalink to &quot;Advanced — senior-grade depth (~60+ min each)&quot;">​</a></h3><ol start="4"><li><strong>GitOps with ArgoCD</strong> (~90 min) — local kind cluster + ArgoCD. Git repo with app manifests. ArgoCD syncs cluster to repo state. Make a change in git, observe auto-sync. Roll back via git revert.</li><li><strong>Linux production debugging walkthrough</strong> (~75 min) — simulate a hung Spring Boot app (deadlock or memory leak). Use <code>jstack</code> for thread dump, <code>jmap -dump</code> for heap dump, <code>lsof</code> for open files, <code>ss -tnp</code> for network connections. Document the diagnosis sequence.</li></ol><h3 id="hands-on-time-summary-practice-advanced-only" tabindex="-1">Hands-on time summary (Practice + Advanced only) <a class="header-anchor" href="#hands-on-time-summary-practice-advanced-only" aria-label="Permalink to &quot;Hands-on time summary (Practice + Advanced only)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tier</th><th>Total time</th><th>Weeks @ 10–12 hrs/wk</th><th>Actual time</th></tr></thead><tbody><tr><td>Practice (mid-level)</td><td>~2.75 hrs</td><td>~0.25 wk</td><td></td></tr><tr><td>Advanced (senior-grade)</td><td>~2.75 hrs</td><td>~0.25 wk</td><td></td></tr><tr><td><strong>Combined hands-on (Practice + Advanced)</strong></td><td><strong>~5.5 hrs</strong></td><td><strong>~0.5 wk</strong></td><td></td></tr></tbody></table><blockquote><p>Warm-up exercises (counted in main Time summary above) total ~2 hrs for Part 22 across 5 in-table warm-ups.</p></blockquote><h2 id="quick-recall" tabindex="-1">Quick recall <a class="header-anchor" href="#quick-recall" aria-label="Permalink to &quot;Quick recall&quot;">​</a></h2><p><strong>Q. Multi-stage Docker build — what&#39;s the win?</strong> A. Smaller image (build deps left behind), better security (no build tools in runtime), faster cold start. Build stage has JDK + Maven; runtime stage has only JRE + jar.</p><p><strong>Q. K8s liveness vs readiness probe?</strong> A. Liveness: &quot;alive?&quot; — fail → K8s restarts. Readiness: &quot;ready to serve?&quot; — fail → K8s removes from Service endpoints, no restart.</p><p><strong>Q. Terraform state — where to store?</strong> A. Remote backend (S3 + DynamoDB lock, or Terraform Cloud). Never local for teams — race conditions, lost state, no collaboration.</p><p><strong>Q. Canary vs blue-green deployment.</strong> A. Blue-green: atomic switch between two complete environments. Canary: gradual traffic shift (1% → ... → 100%) with metric gating. Canary is risk-aware; blue-green is fast rollback.</p><p><strong>Q. JVM in container — memory gotcha?</strong> A. Pre-Java 8u131, JVM ignored cgroup limits → set max heap to host RAM → OOMKilled. Modern: <code>-XX:+UseContainerSupport</code> (default) + <code>-XX:MaxRAMPercentage=75.0</code> for headroom.</p><p><strong>Q. Linux debug commands — what does <code>lsof -i :8080</code> show?</strong> A. Process holding port 8080. Useful for &quot;what&#39;s running on this port?&quot; Variants: <code>lsof -p &lt;pid&gt;</code> for files held by a process, <code>lsof | grep deleted</code> for leaked file descriptors.</p>',28)])])}const m=e(s,[["render",a]]);export{p as __pageData,m as default};
